def normalize_label(label):
    """Normalize a reference label: case-insensitive, whitespace collapsed."""
    return re.sub(r"\s+", " ", label.strip()).lower()


def parse_ref_definitions(text):
    """Collect reference definitions from text.

    Returns a dict mapping normalized label to target, skipping code
    fences. A definition line is ``[label]: destination`` with an
    optional ``"title"``; ``<...>`` wrappers around the destination
    are stripped.
    """
    defs = {}
    in_fence = False
    for line in text.splitlines():
        if FENCE_RE.match(line):
            in_fence = not in_fence
            continue
        if in_fence:
            continue
        m = REF_DEF_RE.match(line)
        if not m:
            continue
        target = m.group(2)
        if target.startswith("<") and target.endswith(">"):
            target = target[1:-1]
        defs[normalize_label(m.group(1))] = target
    return defs


